import { Response } from "express"

type TMeta = {
   page : number,
   limit : number,
   total : number,
   totalPages : number
}

type TReponseData<T> = {
   success : boolean,
   statusCode : number,
   message : string,
   data : T,
   meta? : TMeta
}

export const sendResponse =<T> (res : Response, data :TReponseData<T>) => {
   res.status(data.statusCode).json({
      success : data.success,
      statusCode : data.statusCode,
      message : data.message,
      data : data.data,
      meta :data.meta
   })
}